def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def move_toward(src, dst):
        sx, sy = src
        tx, ty = dst
        return [clamp_step(tx - sx), clamp_step(ty - sy)]

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    env = observation.get("environment_name", "")
    sx, sy = pos(observation.get("self_position"))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    gw = observation.get("grid_width", 0)
    gh = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return move_toward((sx, sy), (ox, oy))
        corners = []
        if gw and gh:
            corners = [(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)]
        else:
            corners = [(-10, -10), (-10, 10), (10, -10), (10, 10)]
        target = max(corners, key=lambda c: dist(c, (ox, oy)))
        return move_toward((sx, sy), target)

    if env == "territory_control":
        candidates = []
        for key in ("unclaimed_cells", "opponent_territory", "neutral_cells", "targets", "frontier_cells"):
            items = observation.get(key) or []
            if items:
                candidates = items
                break
        if not candidates:
            # Bias away from opponent if no territory target is exposed.
            return move_toward((sx, sy), (sx + clamp_step(sx - ox), sy + clamp_step(sy - oy)))
        best = min(candidates, key=lambda c: dist(pos(c), (sx, sy)))
        return move_toward((sx, sy), pos(best))

    resources = observation.get("resources") or observation.get("resource_positions") or observation.get("items") or []
    if resources:
        best = min(resources, key=lambda c: dist(pos(c), (sx, sy)))
        return move_toward((sx, sy), pos(best))

    # Generic fallback: either chase opponent or head to center if available.
    center = (gw // 2, gh // 2) if gw and gh else (sx, sy)
    if env == "resource_collection":
        # Prefer resources, otherwise drift toward center for exploration.
        return move_toward((sx, sy), center)

    # Default robust behavior: avoid opponent slightly while staying stable.
    return move_toward((sx, sy), (sx + clamp_step(sx - ox), sy + clamp_step(sy - oy)))

